/**
 * Import fresh Holoo ERP data (products + suppliers/stakeholders) into SarResid.
 * - Source JSON: scripts/data/products-holoo.json + suppliers-holoo.json
 *   (generated by scripts/convert-holoo-export.py from upload/inventory.xls +
 *   upload/stakeholders-new.xlsx)
 * - Upserts by `code`, keeping existing ids stable (planograms / orders /
 *   product images reference ids).
 * - Removes products/suppliers that disappeared from the export, UNLESS they
 *   are referenced (order items, margin items, planogram cells, cheques,
 *   orders) — those are kept but deactivated.
 * - Supplier extras (economicCode/nationalId/postalCode) stored as the JSON
 *   envelope in `note`, same contract as the suppliers API. Existing envelope
 *   is preserved when the export has nothing to offer.
 *
 * Run: bunx tsx scripts/import-holoo.ts
 */
import { db } from '../src/lib/db'
import * as fs from 'fs'
import * as path from 'path'

type ProductRow = {
  name: string; code: string; unit: string; mainGroup: string; subGroup: string
  sellPrice: number; sellPrice2: number; lastBuyPrice: number
  stock: number; reorderLevel: number | null; status: string; active: boolean
  barcodes: string[]
}

type SupplierRow = {
  name: string; code: string; phone: string | null; job: string | null
  classification: string | null; intermediary: string | null
  balance: number; creditLimit: number; status: string; note: string | null
  economicCode: string | null; nationalId: string | null; postalCode: string | null
}

const DATA = path.join(__dirname, 'data')

function supplierNoteEnvelope(row: SupplierRow, existingNote: string | null): string | null {
  const extras = {
    note: row.note ?? null,
    economicCode: row.economicCode ?? null,
    nationalId: row.nationalId ?? null,
    postalCode: row.postalCode ?? null,
  }
  const hasAny = extras.note || extras.economicCode || extras.nationalId || extras.postalCode
  if (hasAny) return JSON.stringify(extras)
  // nothing new — keep whatever envelope/text existed before
  return existingNote
}

async function importProducts() {
  const rows: ProductRow[] = JSON.parse(fs.readFileSync(path.join(DATA, 'products-holoo.json'), 'utf8'))
  console.log(`[products] export rows: ${rows.length}`)

  const existing = await db.product.findMany({ select: { id: true, code: true } })
  const byCode = new Map(existing.map(p => [p.code ?? '', p.id]))
  console.log(`[products] existing in DB: ${existing.length}`)

  let created = 0, updated = 0
  const seen = new Set<string>()

  for (const r of rows) {
    if (!r.code || seen.has(r.code)) continue
    seen.add(r.code)
    const data = {
      name: r.name,
      code: r.code,
      unit: r.unit || 'عدد',
      category: r.subGroup || r.mainGroup || null,
      mainGroup: r.mainGroup || null,
      subGroup: r.subGroup || null,
      sellPrice: r.sellPrice || 0,
      sellPrice2: r.sellPrice2 || 0,
      lastBuyPrice: r.lastBuyPrice || 0,
      stock: r.stock || 0,
      reorderLevel: r.reorderLevel ?? null,
      status: r.status || 'فعال',
      active: r.active !== false,
      barcodesJson: JSON.stringify(r.barcodes?.length ? r.barcodes : []),
    }
    const id = byCode.get(r.code)
    if (id) {
      await db.product.update({ where: { id }, data })
      updated++
    } else {
      await db.product.create({ data })
      created++
    }
  }
  console.log(`[products] created: ${created}, updated: ${updated}`)

  // removals — keep referenced ones (deactivate instead of delete)
  const toRemove = existing.filter(p => p.code && !seen.has(p.code))
  if (toRemove.length) {
    // gather every productId reference
    const orderItems = await db.orderItem.findMany({ select: { productId: true }, where: { productId: { not: null } } })
    const marginItems = await db.marginItem.findMany({ select: { productId: true }, where: { productId: { not: null } } })
    const planos = await db.planogram.findMany({ select: { cellsJson: true } })
    const cellRefs = new Set<string>()
    for (const p of planos) {
      try {
        const arr = JSON.parse(p.cellsJson) as (string | null)[]
        for (const c of arr) if (c) cellRefs.add(c)
      } catch { /* ignore */ }
    }
    const imgKeys = new Set((await db.productImage.findMany({ select: { key: true } })).map(i => i.key))
    const referenced = new Set<string>([
      ...orderItems.map(i => i.productId!).filter(Boolean),
      ...marginItems.map(i => i.productId!).filter(Boolean),
      ...cellRefs,
    ])
    let deleted = 0, deactivated = 0
    for (const p of toRemove) {
      if (referenced.has(p.id)) {
        await db.product.update({ where: { id: p.id }, data: { active: false, status: 'غیر فعال' } })
        deactivated++
      } else {
        await db.product.delete({ where: { id: p.id } })
        deleted++
      }
    }
    console.log(`[products] removed: ${deleted} deleted, ${deactivated} deactivated (still referenced)`)
  }
}

async function importSuppliers() {
  const rows: SupplierRow[] = JSON.parse(fs.readFileSync(path.join(DATA, 'suppliers-holoo.json'), 'utf8'))
  console.log(`[suppliers] export rows: ${rows.length}`)

  const existing = await db.supplier.findMany({ select: { id: true, code: true, note: true } })
  const byCode = new Map(existing.map(s => [s.code ?? '', s]))
  console.log(`[suppliers] existing in DB: ${existing.length}`)

  let created = 0, updated = 0
  const seen = new Set<string>()

  for (const r of rows) {
    if (!r.code || seen.has(r.code)) continue
    seen.add(r.code)
    const ex = byCode.get(r.code)
    const data = {
      name: r.name,
      code: r.code,
      phone: r.phone ?? null,
      job: r.job ?? null,
      classification: r.classification ?? null,
      intermediary: r.intermediary ?? null,
      balance: r.balance ?? 0,
      creditLimit: r.creditLimit || 0,
      status: r.status || 'فعال',
    }
    if (ex) {
      await db.supplier.update({
        where: { id: ex.id },
        data: { ...data, note: supplierNoteEnvelope(r, ex.note) },
      })
      updated++
    } else {
      await db.supplier.create({
        data: { ...data, note: supplierNoteEnvelope(r, null) },
      })
      created++
    }
  }
  console.log(`[suppliers] created: ${created}, updated: ${updated}`)

  const toRemove = existing.filter(s => s.code && !seen.has(s.code))
  if (toRemove.length) {
    const orderRefs = new Set(
      (await db.order.findMany({ select: { supplierId: true }, where: { supplierId: { not: null } } }))
        .map(o => o.supplierId!).filter(Boolean)
    )
    const marginRefs = new Set(
      (await db.marginInvoice.findMany({ select: { supplierId: true }, where: { supplierId: { not: null } } }))
        .map(m => m.supplierId!).filter(Boolean)
    )
    const chequeRefs = new Set(
      (await db.cheque.findMany({ select: { supplierId: true }, where: { supplierId: { not: null } } }))
        .map(c => c.supplierId!).filter(Boolean)
    )
    let deleted = 0, deactivated = 0
    for (const s of toRemove) {
      if (orderRefs.has(s.id) || marginRefs.has(s.id) || chequeRefs.has(s.id)) {
        await db.supplier.update({ where: { id: s.id }, data: { status: 'غیر فعال' } })
        deactivated++
      } else {
        await db.supplier.delete({ where: { id: s.id } })
        deleted++
      }
    }
    console.log(`[suppliers] removed: ${deleted} deleted, ${deactivated} deactivated (still referenced)`)
  }
}

async function main() {
  await importProducts()
  await importSuppliers()
  const counts = {
    products: await db.product.count(),
    suppliers: await db.supplier.count(),
  }
  console.log('[done]', counts)
}

main().catch(e => { console.error(e); process.exit(1) })
